contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount <= address(this).balance);

        // Build credit of `amount` for this contract, then withdraw it fully.
        c.deposit{value: amount}();
        uint contractBalAfterDeposit = address(c).balance;
        uint testBalAfterDeposit = address(this).balance;
        c.withdrawAll();

        // Now credit is zero. A zero-value deposit must not revert and must not move Ether.
        bool reverted;
        try c.deposit{value: 0}() { reverted = false; } catch { reverted = true; }

        // A subsequent withdrawAll with zero credit must also transfer nothing.
        c.withdrawAll();

        assert(
            !reverted &&
            address(c).balance == contractBalAfterDeposit &&
            address(this).balance == testBalAfterDeposit - amount
        );
    }

    receive() external payable {}
}

